mapper.select:
SELECT stat_date, SUM(new_customer_count) AS new_customer_count, SUM(high_intent_count) AS high_intent_count, SUM(pending_task_count) AS pending_task_count, SUM(expected_amount) AS expected_amount, SUM(forget_task_count) AS forget_task_count FROM report_daily_stat WHERE 1 = 1
AND stat_date >= #{query.dateStart}
AND stat_date <= #{query.dateEnd}
AND dept_id = #{query.deptId}
GROUP BY stat_date ORDER BY stat_date ASC

SELECT COUNT(*)
FROM crm_customer
WHERE deleted = 0

    AND status = #{status}


    AND DATE(created_at) >= #{query.dateStart}


    AND DATE(created_at) <= #{query.dateEnd}


    AND dept_id = #{query.deptId}

SELECT IFNULL(source, 'UNKNOWN') AS source, COUNT(*) AS customer_count, COUNT(CASE WHEN status = 'DEAL' THEN 1 END) AS deal_customer_count, CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(COUNT(CASE WHEN status = 'DEAL' THEN 1 END) / COUNT(*), 4) END AS deal_rate FROM crm_customer WHERE deleted = 0
AND DATE(created_at) >= #{query.dateStart}
AND DATE(created_at) <= #{query.dateEnd}
AND dept_id = #{query.deptId}
GROUP BY IFNULL(source, 'UNKNOWN') ORDER BY customer_count DESC
